<script>
  import { isFunction } from '@splendidlabz/utils'
  import { randomString } from '@splendidlabz/utils/dom'
  import { applyTransition, init } from '../../utils/index.js'
  import { reloadScripts } from '../../utils/loadscripts.js'
  import { IconSnippet } from '../Icon/IconSnippet.svelte'
  import { MarkdownSnippet } from '../Markdown/MarkdownSnippet.svelte'

  let {
    id = randomString(9),
    class: klass,
    titleTag = 'h3',
    transition = 'slide',
    title,
    content,
    open = $bindable(false),
    onToggle = undefined,
    children,
    ...rest
  } = $props()

  // svelte-ignore state_referenced_locally
  const {
    titleClass,
    contentClass,
    buttonClass,
    icon = 'tabler:chevron-right',
    iconClass,
    iconPosition = 'end',
    useMarkdown = true,
  } = rest

  init(() => {
    if (!title) console.warn('Accordion: No title provided')
    if (!content && !children) console.warn('Accordion: No content provided')
  })

  function handleClick(event) {
    open = !open
    if (isFunction(onToggle)) onToggle(open)
    if (open) closeOtherAccordions(event)
  }

  function handleKeydown(event) {
    const { key } = event
    if (key === 'Escape') closeAccordion()
  }

  function closeAccordion() {
    open = false
    if (isFunction(onToggle)) onToggle(false)
  }

  function closeOtherAccordions(event) {
    const container = event.target.closest('.accordion-stack')
    if (!container) return
    const closeButtons = container.querySelectorAll('.accordion-close-button')
    closeButtons.forEach(button => button.click())
    open = true
  }
</script>

<!-- Accordion HTML -->
<div class="accordion {klass}" class:open>
  <svelte:element this={titleTag} class="accordion-title {titleClass}">
    <button
      class="accordion-button {buttonClass}"
      aria-controls={id}
      aria-expanded={open}
      onclick={handleClick}
      onkeydown={handleKeydown}
    >
      <!-- Icon (if start) -->
      {#if iconPosition === 'start'}
        {@render IconSnippet.block({ icon, iconClass })}
      {/if}

      <!-- Title -->
      {@render MarkdownSnippet.inline(title, useMarkdown)}

      <!-- Icon (if end) -->
      {#if iconPosition === 'end'}
        {@render IconSnippet.block({ icon, iconClass })}
      {/if}
    </button>
  </svelte:element>

  {#if open}
    <div
      {id}
      class="accordion-content {contentClass}"
      use:reloadScripts
      transition:applyTransition={{
        transition,
      }}
    >
      {@render MarkdownSnippet.block(content || children, useMarkdown)}
    </div>
  {/if}

  <!-- Hidden button for closing multiple accordions. Accessible via JS only -->
  <button
    style="display:none"
    class="accordion-close-button"
    aria-hidden="true"
    hidden
    onclick={closeAccordion}
    tabindex="-1"
  ></button>
</div>
